import assert from 'node:assert/strict';
import {buildGGBetHealth,buildPinnacleFamilyHealth} from './bookmaker-source-health.mjs';
const now=Date.parse('2026-10-09T21:55:00Z');
const fresh={generatedAt:'2026-10-09T21:50:18Z',source:'ggbet-objective',connected:true,usable:true,state:'CONNECTED_USABLE',events:7,markets:548,errors:[],discovery:{lol:4,dota2:6},fetched:{selected:10,successful:10,failed:0,objectiveMarkets:548}};
const x=buildGGBetHealth(fresh,{now});
assert.equal(x.ok,true);assert.equal(x.usable,true);assert.equal(x.events,7);assert.equal(x.markets,548);
assert.equal(x.fetchSelected,10);assert.equal(x.fetchSuccessful,10);assert.equal(x.fetchFailed,0);
assert.equal(x.exactMatches,null,'do not fabricate exact matching counts');
assert.equal(x.rejectedIdentity,null,'do not fabricate rejection counts');
assert.equal(x.fetchedAt,fresh.generatedAt);
const stale=buildGGBetHealth(fresh,{now:now+70*60*1000});
assert.equal(stale.ok,false);assert.equal(stale.state,'STALE');
const absent=buildGGBetHealth({}, {now});
assert.equal(absent.ok,false);assert.equal(absent.state,'UNAVAILABLE');
const p=buildPinnacleFamilyHealth({pinnacle:{ok:false,status:500,errors:['HTTP 403']},pinnwire:{ok:true,usable:true,status:200,state:'CONNECTED_USABLE',events:13,markets:60}});
assert.equal(p.usable,true);assert.equal(p.preferredPath,'pinnwire');assert.equal(p.sourceFamily,'pinnacle');
assert.equal(p.nativeDirectStatus,500);assert.equal(p.fallbackStatus,200);
assert.equal(buildPinnacleFamilyHealth({pinnacle:{ok:false},pinnwire:{ok:false,usable:false}}).usable,false);
const pAwsDirect=buildPinnacleFamilyHealth({pinnacle:{ok:false,status:500},pinnwire:{ok:true,status:200,events:32,acceptedEvents:19,acceptedMarkets:871}});
assert.equal(pAwsDirect.usable,true,'verified AWS PinnWire collector must count as a usable Pinnacle-family source');
assert.equal(pAwsDirect.preferredPath,'pinnwire');
assert.equal(pAwsDirect.events,19,'prefer accepted, not raw PinnWire event count');
assert.equal(pAwsDirect.markets,871);
assert.equal(buildPinnacleFamilyHealth({pinnwire:{ok:true,status:200,acceptedEvents:0,acceptedMarkets:0}}).usable,false,'empty collector must not count');
console.log('GGBET_AND_PINNACLE_FAMILY_TELEMETRY_VERIFIED');